  qs: [
    { efig: "layoutSizes", q: "`wrap_content` và `match_parent` khác nhau thế nào?", c: ["`wrap_content`: vừa đủ nội dung; `match_parent`: chiếm hết kích thước view cha"], w: ["Ngược lại", "Giống nhau", "`wrap_content` luôn bằng 0dp"], e: "Trong ConstraintLayout, `0dp` (match constraint) nghĩa là giãn theo ràng buộc." },
    { q: "`LinearLayout` với `android:orientation=\"vertical\"` sắp xếp view con thế nào?", c: ["Lần lượt từ trên xuống dưới"], w: ["Từ trái sang phải", "Chồng lên nhau", "Theo lưới"], e: "`horizontal` xếp từ trái sang phải. FrameLayout xếp chồng lên nhau." },
    { q: "Hai nút trong LinearLayout ngang cùng `layout_width=\"0dp\"` và `layout_weight=\"1\"`. Kết quả?", c: ["Mỗi nút chiếm một nửa chiều rộng"], w: ["Hai nút rộng 0, không hiện", "Nút đầu chiếm hết", "Lỗi layout"], e: "`layout_weight` chia phần không gian còn lại theo tỉ lệ." },
    { q: "Ưu điểm chính của `ConstraintLayout`?", c: ["Dựng layout phức tạp mà không cần lồng nhiều tầng layout, định vị view bằng ràng buộc"], w: ["Chỉ dùng cho danh sách", "Không cần khai báo id", "Tự động gọi API"], e: "Lồng nhiều LinearLayout làm việc đo và vẽ chậm hơn." },
    { efig: "visibility", q: "`View.GONE` khác `View.INVISIBLE` thế nào?", c: ["GONE: ẩn và không chiếm chỗ; INVISIBLE: ẩn nhưng vẫn chiếm chỗ"], w: ["Giống nhau", "GONE vẫn chiếm chỗ", "INVISIBLE xoá view khỏi bộ nhớ"], e: "Câu hỏi nhỏ nhưng rất hay gặp." },
    { efig: "recycler", q: "RecyclerView cần những thành phần nào để hoạt động?", c: ["Adapter", "ViewHolder", "LayoutManager"], w: ["Intent", "BroadcastReceiver"], e: "Thiếu LayoutManager, RecyclerView không hiển thị gì." },
    { q: "Đổ dữ liệu của item tại `position` vào view được thực hiện ở hàm nào của Adapter?", c: ["`onBindViewHolder`"], w: ["`onCreateViewHolder`", "`getItemCount`", "`onCreate`"], e: "`onCreateViewHolder` chỉ inflate layout và tạo ViewHolder (ít lần); `onBindViewHolder` được gọi mỗi khi item hiện ra." },
    { q: "Vì sao không nên gọi `notifyDataSetChanged()` mỗi khi list thay đổi?", c: ["Vẽ lại toàn bộ danh sách, mất animation, tốn hiệu năng; nên dùng `ListAdapter` + `DiffUtil`"], w: ["Hàm này đã bị xoá khỏi Android", "Gây crash ngay", "Không có lý do"], e: "DiffUtil so sánh list cũ và mới để chỉ cập nhật item thay đổi." },
    { q: "`DiffUtil.ItemCallback` cần cài đặt hai hàm nào?", c: ["`areItemsTheSame` (cùng một item, thường so id)", "`areContentsTheSame` (nội dung có thay đổi không)"], w: ["`onCreate`", "`onBind`"], e: "Viết sai `areItemsTheSame` làm animation và cập nhật bị sai." },
    { q: "Hiển thị danh sách dạng lưới 2 cột với RecyclerView dùng gì?", c: ["`GridLayoutManager(context, 2)`"], w: ["`LinearLayoutManager(context, 2)`", "Hai RecyclerView đặt cạnh nhau", "`GridView` trong LinearLayout"], e: "`StaggeredGridLayoutManager` cho lưới kiểu Pinterest (item cao thấp khác nhau)." },
    { q: "Xử lý click vào item của RecyclerView, cách gọn gàng thường dùng?", code: "class UserAdapter(\n    private val onClick: (User) -> Unit\n) : ListAdapter<User, UserAdapter.VH>(Diff) {\n    // trong onBindViewHolder:\n    // val user = getItem(position)\n    // holder.itemView.setOnClickListener { onClick(user) }\n}", c: ["Truyền lambda callback vào Adapter, Activity/Fragment quyết định làm gì khi click"], w: ["Adapter tự gọi `startActivity`", "Dùng biến static lưu item được click", "RecyclerView không hỗ trợ click"], e: "Adapter chỉ lo hiển thị, không chứa logic điều hướng." },
    { q: "Trong Fragment dùng ViewBinding, vì sao phải gán `_binding = null` ở `onDestroyView`?", c: ["View của Fragment bị huỷ nhưng Fragment vẫn sống (vd trong back stack); giữ binding sẽ gây memory leak"], w: ["Để app chạy nhanh hơn", "Bắt buộc theo cú pháp Kotlin", "Để xoá Fragment"], e: "Mẫu chuẩn: `private var _binding: FragmentXBinding? = null` và `private val binding get() = _binding!!`." },
    { q: "Đoạn code sau thay Fragment trong container. `addToBackStack(null)` có tác dụng gì?", code: "supportFragmentManager.beginTransaction()\n    .replace(R.id.container, DetailFragment())\n    .addToBackStack(null)\n    .commit()", c: ["Cho phép bấm Back để quay lại Fragment trước"], w: ["Đóng Activity", "Xoá Fragment cũ khỏi bộ nhớ vĩnh viễn", "Không có tác dụng"], e: "Thiếu `addToBackStack`, bấm Back sẽ thoát luôn Activity." },
    { q: "Navigation Component (XML) gồm những thành phần nào?", c: ["Navigation graph (`nav_graph.xml`)", "`NavHostFragment`", "`NavController` (`findNavController().navigate(...)`)"], w: ["`RecyclerView.Adapter`", "`BroadcastReceiver`"], e: "Safe Args giúp truyền tham số giữa các màn an toàn về kiểu." },
    { q: "Tạo nền bo góc cho button mà không cần ảnh, cách thông dụng?", c: ["Drawable XML `<shape>` với `<corners android:radius=\"12dp\"/>`"], w: ["Cắt ảnh PNG bo góc", "Khai báo trong `strings.xml`", "Không làm được bằng XML"], e: "Hoặc dùng `MaterialButton` với thuộc tính `app:cornerRadius`." },
    { q: "Hỗ trợ dark mode với hệ thống View, đặt màu cho chế độ tối ở đâu?", c: ["Thư mục `values-night/` (colors.xml, themes.xml) bên cạnh `values/`"], w: ["Trong Activity bằng if-else", "Trong AndroidManifest", "Không hỗ trợ"], e: "Hệ thống tự chọn tài nguyên theo chế độ sáng/tối." },
    { q: "Ô nhập mật khẩu ẩn ký tự dùng thuộc tính nào?", c: ["`android:inputType=\"textPassword\"`"], w: ["`android:hidden=\"true\"`", "`android:password=\"show\"`", "`android:visibility=\"gone\"`"], e: "inputType còn quyết định loại bàn phím: `number`, `phone`, `textEmailAddress`..." },
    { q: "`ImageView` với `scaleType=\"centerCrop\"` hiển thị ảnh thế nào?", c: ["Phủ kín khung, giữ tỉ lệ, cắt bớt phần thừa"], w: ["Kéo giãn méo ảnh cho vừa khung", "Thu nhỏ để thấy toàn bộ ảnh, chừa khoảng trống", "Không hiển thị"], e: "`fitCenter` hiển thị trọn ảnh, có thể chừa khoảng trống hai bên." },
    { q: "`ScrollView` có giới hạn gì?", c: ["Chỉ được chứa một view con trực tiếp"], w: ["Không cuộn được", "Chỉ chứa ImageView", "Tối đa 10 view"], e: "Muốn nhiều view thì bọc trong một LinearLayout. Danh sách dài thì dùng RecyclerView." },
    { q: "Snackbar khác Toast ở điểm nào?", c: ["Snackbar gắn với layout và có thể kèm nút hành động (vd 'Hoàn tác')"], w: ["Toast có nút hành động, Snackbar thì không", "Giống nhau", "Snackbar chỉ dùng trong Service"], e: "Trong Compose dùng `SnackbarHost` của `Scaffold`." },
    { q: "`findViewById` với id không có trong layout hiện tại thì?", c: ["Trả về null, dùng tiếp sẽ crash NullPointerException"], w: ["Tự tạo view mới", "Lỗi compile", "Trả về view đầu tiên"], e: "ViewBinding tránh được lỗi này vì chỉ sinh field cho view có thật trong layout." },
    { q: "Đặt cỡ chữ trong XML thế nào là đúng?", c: ["`android:textSize=\"16sp\"`"], w: ["`android:textSize=\"16px\"`", "`android:textSize=\"16dp\"`", "`android:textSize=\"16\"`"], e: "Dùng `sp` cho chữ để tôn trọng cài đặt cỡ chữ của người dùng." }
  ]
